<?php if($hotelResults): ?><div class="hotel-sort"><label for="hotel-sort">並び順</label><select id="hotel-sort"><option value="recommended">おすすめ順</option><option value="price">参考価格が安い順</option><option value="rating">評価が高い順</option></select></div><div class="hotel-results" aria-label="ホテル検索結果" data-hotel-destination="<?= $h($hotelValues['hotel_destination']) ?>" data-check-in="<?= $h($hotelValues['check_in_date']) ?>" data-check-out="<?= $h($hotelValues['check_out_date']) ?>" data-adults="<?= $h($hotelValues['hotel_adults']) ?>" data-children="<?= $h($hotelValues['hotel_children']) ?>"><?php foreach($hotelResults as $hotelIndex=>$hotel): ?><article class="hotel-summary-card" data-property-token="<?= $h($hotel['property_token']) ?>" data-nights="<?= $hotel['nights'] ?>" data-recommended="<?= $hotelIndex ?>" data-price="<?= $hotel['lowest']['nightly'] ?? '' ?>" data-rating="<?= $h($hotel['rating_10']) ?>"<?= !$hotel['lowest']&&$hotel['property_token']!==''?' data-detail-pending':'' ?><?= $hotelIndex>=5?' hidden data-extra-hotel':'' ?>>
<div class="hotel-summary-photo-wrap"><?php if($hotel['image']!==''): ?><img class="hotel-summary-photo" src="<?= $h($hotel['image']) ?>" alt="<?= $h($hotel['name']) ?>" loading="lazy"><?php else: ?><div class="hotel-summary-photo hotel-summary-photo-placeholder" aria-label="画像なし">No image</div><?php endif ?><?php if($hotel['image_count']>1): ?><span class="hotel-photo-count">1 / <?= number_format($hotel['image_count']) ?></span><?php endif ?></div><div class="hotel-summary-main"><h3><?= $h($hotel['name']) ?></h3><p class="hotel-class-row"><?php if($hotel['stars']>0): ?><span class="hotel-stars" aria-label="<?= $hotel['stars'] ?>つ星"><?= str_repeat('★',$hotel['stars']) ?></span><?php endif ?><span><?= $h($hotel['type']) ?></span></p><?php if($hotel['rating_10']!==''): ?><p class="hotel-review-row"><b><?= $h($hotel['rating_10']) ?></b><strong><?= $h($hotel['rating_label']) ?></strong><?php if($hotel['reviews']>0): ?><span>（<?= number_format($hotel['reviews']) ?>件の評価）</span><?php endif ?></p><?php endif ?><?php if($hotel['area']!==''): ?><p class="hotel-location-row">⌖ <?= $h($hotel['area']) ?></p><?php endif ?><?php if($hotel['access']!==''): ?><p class="hotel-access-row">◇ <?= $h(mb_strimwidth($hotel['access'],0,80,'…')) ?></p><?php endif ?><?php if($hotel['amenities']): ?><p class="hotel-summary-amenities"><?= $h(implode(' / ',array_slice($hotel['amenities'],0,4))) ?></p><?php endif ?></div>
<div class="hotel-summary-price" data-offer-panel><?php if($hotel['lowest']): ?><div class="hotel-best-offer"><span class="hotel-reference-title">参考最安値</span><b data-best-site><?= $h($hotel['lowest']['site']) ?></b><span class="hotel-cancellation" data-cancellation<?= $hotel['lowest']['free_cancellation']?'':' hidden' ?>>✓ キャンセル無料</span><div class="hotel-price-action"><div><strong data-best-nightly>¥<?= number_format($hotel['lowest']['nightly']) ?> / 泊</strong><small data-best-total><?= $hotel['nights'] ?>泊参考 ¥<?= number_format($hotel['lowest']['total']) ?></small></div><a class="hotel-compare-button" data-best-link href="<?= $h($hotel['lowest']['url']) ?>" target="_blank" rel="sponsored noopener">料金プランを見る ›</a></div><small class="google-price-note">Google Hotels掲載価格より</small></div><div class="hotel-compare-prices" data-other-prices<?= count($hotel['offers'])>1?'':' hidden' ?>><small>その他の掲載価格</small><?php foreach(array_slice($hotel['offers'],1,2) as $offer): ?><span><b><?= $h($offer['site']) ?></b> ¥<?= number_format($offer['nightly']) ?> / 泊</span><?php endforeach ?></div><?php elseif($hotel['property_token']!==''): ?><button type="button" class="hotel-compare-button" data-load-hotel-price>参考料金を取得</button><small class="google-price-note">クリック時のみ料金を検索します</small><?php else: ?><p class="hotel-no-price" data-no-price>参考価格は取得できませんでした</p><?php endif ?></div></article><?php endforeach ?></div><?php if(count($hotelResults)>5): ?><button type="button" class="hotel-results-toggle" data-step="5">もっと見る</button><?php endif ?><p class="price-note">料金は検索時点の参考価格です。税・サービス料、空室状況、プラン条件等により実際の料金は異なる場合があります。詳細料金はボタン操作時のみ取得します。</p>
